<script setup lang="ts">import {computed} from 'vue';import type {Risk,Task} from '../types/domain';import {pct} from '../utils/format';const props=defineProps<{risk:Risk;tasks:Task[]}>();const rows=computed(()=>props.risk.task_criticality.slice().sort((a,b)=>b.criticality-a.criticality||a.task_id.localeCompare(b.task_id)));const name=(id:string)=>props.tasks.find(t=>t.task_id===id)?.name;</script><template><div class="criticality-list"><div v-for="r in rows" :key="r.task_id" class="criticality-row"><span><b>{{r.task_id}}</b> {{name(r.task_id)}}</span><div class="bar-track"><i :style="{width:(r.criticality*100)+'%'}"/></div><strong>{{pct(r.criticality)}}</strong><small>{{r.critical_count}} / {{r.denominator}}</small></div></div><p class="muted">分子为每次模拟总时差≤{{risk.tolerance_hours}}小时的次数；分母为全部{{risk.samples}}次抽样，不只统计基线关键任务。</p></template>